using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class StageTests52 {
 static readonly List<string> passed=new List<string>();
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Reject(Action a,string why){bool failed=false;try{a();}catch(ArgumentException){failed=true;}Check(failed,why);}
 static ResolvedShade52.Stamp Stamp(bool final,int count){return new ResolvedShade52.Stamp{actor="test-actor",view="test-view",sourceId="saved58/CPU-replay-not-live",stage=final?"final/Qprime":"initial/Q",producer="saved58/diagnostic-contract",frame=1,serial=1,width=count,height=1};}
 public static void Main(string[] args){
  var json=new JavaScriptSerializer();var f=json.Deserialize<RegionBridgeTests.Fixture>(File.ReadAllText(args[0]));
  var families=f.records.Select(r=>r.family).ToArray();var settings=f.records.Select(r=>r.settings).ToArray();
  var regions=f.records.Select((r,i)=>new ResolvedRegionInput.Region{id="test-only/region/"+i,family=i,confirmed=true,decisionId="test-contract-not-inferred-face"}).ToArray();
  Func<bool,ResolvedRegionInput.Cell[]> cells=final=>f.rows.Select(r=>new ResolvedRegionInput.Cell{sourceId=Stamp(final,64).sourceId,regionId=regions[r.family].id,k=final?r.kPrime:r.k,opaqueInterior=r.boundOpaque,witness=r.boundOpaque?families[r.family].samples.Single(s=>s.id==r.sourceSampleId):null}).ToArray();
  Func<bool,ResolvedShade52.Shade> shade=final=>new ResolvedShade52.Shade{stamp=Stamp(final,64),appliedQ=f.rows.Select(r=>(float)(final?r.kPrime:r.k)/(settings[r.family].count-1)).ToArray(),levels=f.rows.Select(r=>settings[r.family].count).ToArray(),known=f.rows.Select(r=>r.boundOpaque).ToArray()};
  Func<ResolvedShade52.Stamp,ResolvedShade52.Shade,ResolvedRegionInput.Cell[],ResolvedShade52.Packet> build=(stamp,shadeInput,c)=>ResolvedShade52.Build(stamp,shadeInput,families,settings,regions,c);
  var a=build(Stamp(false,64),shade(false),cells(false));var b=build(Stamp(true,64),shade(true),cells(true));int oldEqualsQ=0;
  for(int i=0;i<64;i++)if(f.rows[i].boundOpaque){Check(ResolvedRegionInput.LookupRGB8(a.lut,i).SequenceEqual(f.rows[i].initialRGB8),"52 initial saved RGB");Check(ResolvedRegionInput.LookupRGB8(b.lut,i).SequenceEqual(f.rows[i].finalRGB8),"52 final saved RGB");Check(b.appliedQ[i]==(float)b.lut.index[i]/(settings[f.rows[i].family].count-1),"52 direct Q metadata");if(f.rows[i].k==f.rows[i].kPrime)oldEqualsQ++;}
  Check(a.lut.resolved==62&&b.lut.resolved==62&&oldEqualsQ==52,"52 saved evidence coverage");passed.Add("saved58 62 opaque samples / 52 old==q: RGB unchanged; output metadata matches bound integer k");
  int first=Array.FindIndex(f.rows,r=>r.boundOpaque);var q=shade(true);q.appliedQ[first]=q.appliedQ[first]==0?1:0;Reject(()=>build(Stamp(true,64),q,cells(true)),"52 mismatched Q allowed");passed.Add("LUT k versus applied Q mismatch rejected before upload");
  int changed=Array.FindIndex(f.rows,r=>r.boundOpaque&&r.k!=r.kPrime);Check(changed>=0,"52 changed Q fixture missing");q=shade(true);q.appliedQ[changed]=(float)f.rows[changed].k/(settings[f.rows[changed].family].count-1);Reject(()=>build(Stamp(true,64),q,cells(true)),"52 old/proposal mismatch hidden");passed.Add("old Q is not silently accepted as applied Qprime");
  var changes=new Action<ResolvedShade52.Stamp>[] {s=>s.actor+="different",s=>s.view+="different",s=>s.sourceId+="different",s=>s.stage="initial/Q",s=>s.producer+="different",s=>s.frame++,s=>s.serial++,s=>{s.width=32;s.height=2;}};
  foreach(var change in changes){q=shade(true);change(q.stamp);Reject(()=>build(Stamp(true,64),q,cells(true)),"52 foreign stamp accepted");}passed.Add("actor/view/source/stage/producer/frame/serial and equal-area different raster all rejected");
  q=shade(true);q.known[first]=false;Reject(()=>build(Stamp(true,64),q,cells(true)),"52 unknown Q accepted");q=shade(true);q.appliedQ[first]=Single.NaN;Reject(()=>build(Stamp(true,64),q,cells(true)),"52 nonfinite Q accepted");q=shade(true);q.levels[first]++;Reject(()=>build(Stamp(true,64),q,cells(true)),"52 hidden level mapping accepted");passed.Add("missing/NaN Q and producer/palette count mismatch require explicit input correction");
  q=shade(true);q.appliedQ[first]+=0.0000001f;Reject(()=>build(Stamp(true,64),q,cells(true)),"52 tolerance masks distinct label");passed.Add("no epsilon repairs an inconsistent normalized label");
  var observed=Stamp(true,64);q=shade(true);var independent=build(observed,q,cells(true));float saved=independent.appliedQ[first];q.appliedQ[first]=99;observed.sourceId="mutated";Check(independent.appliedQ[first]==saved&&independent.stamp.sourceId!="mutated","52 retains mutable input arrays/stamp");passed.Add("stage metadata output owns its arrays and scope snapshot");
  var missing=f.faceProbes.Select(p=>new ResolvedRegionInput.Region{id=p.regionId,family=1,confirmed=false}).GroupBy(p=>p.id).Select(g=>g.First()).ToArray();
  var face=cells(true).Take(f.faceProbes.Length).ToArray();for(int i=0;i<face.Length;i++){face[i].regionId=f.faceProbes[i].regionId;face[i].witness=null;face[i].opaqueInterior=true;}
  var fs=Stamp(true,face.Length);var fq=new ResolvedShade52.Shade{stamp=Stamp(true,face.Length),appliedQ=Enumerable.Repeat(Single.NaN,face.Length).ToArray(),levels=new int[face.Length],known=new bool[face.Length]};
  var unresolved=ResolvedShade52.Build(fs,fq,families,settings,missing,face);Check(unresolved.lut.resolved==0&&unresolved.lut.unresolved==face.Length,"52 unconfirmed face promoted");passed.Add("actual saved scalp/cheek/AA probes remain unconfirmed; no guessed family or Q");
  var partial=cells(true);partial[first].opaqueInterior=false;q=shade(true);q.known[first]=false;q.appliedQ[first]=Single.NaN;var excluded=build(Stamp(true,64),q,partial);Check(excluded.lut.binding[2*first+1]==0,"52 partial alpha forced opaque");passed.Add("partial alpha remains outside opaque finite-palette coverage");
  foreach(double interval in new[]{0.0,0.5,1.0}) {var alt=settings.Select(s=>new SourcePalette58.Settings{count=s.count,darkLRatio=s.darkLRatio,darkCRatio=s.darkCRatio,gamma=s.gamma,intervalScale=interval}).ToArray();var result=ResolvedShade52.Build(Stamp(true,64),shade(true),families,alt,regions,cells(true));Check(result.appliedQ.SequenceEqual(b.appliedQ)&&result.lut.binding.SequenceEqual(b.lut.binding),"52 palette spacing changes geometry/Q");}passed.Add("palette spacing changes neither region bindings nor applied Q metadata");
  Console.WriteLine(json.Serialize(new{assertionGroups=passed.Count,passed,savedOpaqueSamples=62,sameQ=52,actualFaceBindings=0,semanticRegionTruthValidated=false,newGPUOrUnityCalls=0,productApplied=false}));
 }
}
